/*
 * A099238  Square array read by antidiagonals with rows generated by
 *          1/(1-x-x^(k+1)).
 * https://oeis.org/A099238
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  easy, nonn, tabl
 * Formula:   not stated
 * Range:     u8 n <= 43, u16 n <= 77, u32 n <= 77, u64 n <= 77, u128 n <= 77,
 *            big any n
 * Helpers:   binomial
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A099238: T(n,k)=sum_{j=0..floor(n/(k+1))} binomial(n-k*j,j); a(n) is the square array read by antidiagonals. */
#include "../utils/binomial.h"

seq_t a(idx_t n) {
    /* Find diagonal s such that n < (s+1)(s+2)/2 */
    idx_t s = 0;
    idx_t cum = 1;                           /* (s+1)(s+2)/2 for s=0 */
    while (n >= cum) {
        ++s;
        cum = (s + 1) * (s + 2) / 2;
    }
    /* n lies on diagonal s; index within that diagonal */
    idx_t prev_cum = s * (s + 1) / 2;         /* count of terms before diagonal s */
    idx_t t = n - prev_cum;                  /* row index (n) of T */
    idx_t k = s - t;                          /* column index (k) of T */

    /* Compute T(t,k) */
    seq_t res = 0;
    idx_t maxj = t / (k + 1);                /* floor(t/(k+1)) */
    for (idx_t j = 0; j <= maxj; ++j) {
        res += binomial(t - k * j, j);
    }
    return res;
}
